    {

           using var activity =  StartCallActivity("EditMessageSchedulingStateAsync", typeof(EditMessageSchedulingState).FullName ?? "EditMessageSchedulingStateAsync");

           try
           {
             return client.EditMessageSchedulingStateAsync(chatId, messageId, schedulingState);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
